// 防 DNS rebinding 的关键：校验时和建连时用同一个 IP
public HttpURLConnection openSafe(String url) throws IOException {
    URI uri = URI.create(url).normalize();
    if (!Set.of("http", "https").contains(uri.getScheme())) {
        throw new SecurityException("protocol not allowed: " + uri.getScheme());
    }
    String host = uri.getHost();
    InetAddress[] addrs = InetAddress.getAllByName(host); // 一次解析
    for (InetAddress a : addrs) {
        if (isBlocked(a)) {
            throw new SecurityException("internal ip blocked: " + a.getHostAddress());
        }
    }
    // 用已校验的 IP 直连，绕开 JDK 内部的二次 DNS 解析（防 rebinding）
    InetAddress chosen = addrs[0];
    URL realUrl = new URL(uri.getScheme(), chosen.getHostAddress(), uri.getPort(), uri.getRawPath());
    HttpURLConnection conn = (HttpURLConnection) realUrl.openConnection();
    conn.setRequestProperty("Host", host); // 保留 SNI/Host 头
    conn.setInstanceFollowRedirects(false); // 重定向手动控制，再次走校验
    conn.setConnectTimeout(3000);
    return conn;
}

private boolean isBlocked(InetAddress a) {
    return a.isLoopbackAddress()        // 127/8 ::1
        || a.isLinkLocalAddress()       // 169.254/16 169.254.169.254 元数据
        || a.isSiteLocalAddress()       // 10/8 172.16/12 192.168/16
        || a.isAnyLocalAddress()        // 0.0.0.0
        || a.isMulticastAddress()
        || a.getHostAddress().startsWith("100.100."); // 阿里云元数据
}
